<div class="interactive-wrapper"><div class="card shadow-sm border-0 mb-4" style="border-radius:24px;background:#fff;word-break:break-word"><div class="bg-white border-bottom-0 py-4 px-4" style="border-radius:24px 24px 0 0"><div class="d-flex align-items-center justify-content-between flex-wrap gap-2"><div class="d-flex align-items-center"><div style="width:48px;height:48px;border-radius:14px;display:flex;align-items:center;justify-content:center;font-size:1.25rem;background:#eef2ff"><i class="fas fa-table-cells text-primary"></i></div><div class="ms-3"><h5 class="mb-0 fw-bold text-dark">Periodic Table Analyzer</h5><p class="text-muted small mb-0">Look up element properties by symbol or atomic number</p></div></div><button class="btn btn-sm rounded-pill px-3" id="btn-reset" style="background:#f1f5f9;font-weight:600"><i class="fas fa-undo me-1"></i>Reset</button></div></div><div class="px-4 pb-4" style="overflow-x:auto"><div class="row g-3"><div class="col-md-6"><label class="form-label small fw-bold text-secondary text-uppercase mb-2">Element Symbol</label><input type="text" id="in-sym" class="form-control form-control-lg" value="Fe" placeholder="e.g. Fe, Au, O"></div><div class="col-md-6"><label class="form-label small fw-bold text-secondary text-uppercase mb-2">Or Atomic Number</label><input type="number" id="in-num" class="form-control form-control-lg" placeholder="e.g. 26" min="1" max="118"></div></div><div class="mt-4 text-center"><button class="btn btn-primary btn-lg rounded-pill px-5 shadow-sm" id="btn-calc" style="min-width:260px;max-width:100%"><i class="fas fa-calculator me-2"></i>Calculate</button></div><div class="mt-3 p-3 rounded-4 border" style="background:#f8fafc"><p class="mb-0 small text-muted"><i class="fas fa-info-circle text-primary me-2"></i><b>Database:</b> IUPAC 2021 standard atomic weights</p></div></div></div><div id="res" class="card shadow-sm border-0 d-none mb-4" style="border-radius:24px;background:#fff;word-break:break-word"><div class="bg-white border-bottom-0 py-4 px-4" style="border-radius:24px 24px 0 0"><div class="d-flex align-items-center justify-content-between flex-wrap gap-2"><div class="d-flex align-items-center"><div style="width:48px;height:48px;border-radius:14px;display:flex;align-items:center;justify-content:center;font-size:1.25rem;background:#ecfdf5"><i class="fas fa-check-circle text-success"></i></div><div class="ms-3"><h5 class="mb-0 fw-bold text-dark">Result</h5></div></div><button class="btn btn-success btn-sm rounded-pill px-4 shadow-sm" id="btn-copy"><i class="fas fa-copy me-1"></i>Copy</button></div></div><div class="px-4 pb-4" style="overflow-x:auto"><div class="p-4 rounded-4 bg-light border text-center mb-3"><div class="small fw-bold text-uppercase text-muted mb-1">RESULT</div><div class="display-4 fw-bold text-dark" id="out-main">—</div><div class="small text-muted fw-bold" id="out-unit"></div></div><div id="out-detail" class="row g-3 mb-3"></div><div class="p-4 rounded-4 bg-light border"><h6 class="fw-bold mb-2 small text-uppercase text-muted"><i class="fas fa-lightbulb text-warning me-2"></i>Insights</h6><div id="out-ins" class="small"></div></div></div></div></div><style>.form-control-lg,.form-select-lg{border:1.5px solid #e2e8f0;border-radius:12px;font-size:1.05rem;padding:.75rem 1rem}.form-control:focus,.form-select:focus{border-color:#4f46e5;box-shadow:0 0 0 4px rgba(79,70,229,.1)}</style><script>document.addEventListener("DOMContentLoaded",function(){var PT={H:{n:1,w:1.008,g:"Nonmetal"},He:{n:2,w:4.003,g:"Noble gas"},Li:{n:3,w:6.941,g:"Alkali metal"},Be:{n:4,w:9.012,g:"Alkaline earth"},B:{n:5,w:10.81,g:"Metalloid"},C:{n:6,w:12.011,g:"Nonmetal"},N:{n:7,w:14.007,g:"Nonmetal"},O:{n:8,w:15.999,g:"Nonmetal"},F:{n:9,w:18.998,g:"Halogen"},Ne:{n:10,w:20.180,g:"Noble gas"},Na:{n:11,w:22.990,g:"Alkali metal"},Mg:{n:12,w:24.305,g:"Alkaline earth"},Al:{n:13,w:26.982,g:"Post-transition"},Si:{n:14,w:28.086,g:"Metalloid"},P:{n:15,w:30.974,g:"Nonmetal"},S:{n:16,w:32.06,g:"Nonmetal"},Cl:{n:17,w:35.45,g:"Halogen"},Ar:{n:18,w:39.948,g:"Noble gas"},K:{n:19,w:39.098,g:"Alkali metal"},Ca:{n:20,w:40.078,g:"Alkaline earth"},Fe:{n:26,w:55.845,g:"Transition metal"},Cu:{n:29,w:63.546,g:"Transition metal"},Zn:{n:30,w:65.38,g:"Transition metal"},Ag:{n:47,w:107.87,g:"Transition metal"},Au:{n:79,w:196.97,g:"Transition metal"},Pb:{n:82,w:207.2,g:"Post-transition"},U:{n:92,w:238.03,g:"Actinide"}};document.getElementById("btn-calc").addEventListener("click",function(){var sym=document.getElementById("in-sym").value.trim(),num=document.getElementById("in-num").value,el=null,key="";if(sym){key=sym.charAt(0).toUpperCase()+sym.slice(1).toLowerCase();el=PT[key];}else if(num){num=parseInt(num);for(var k in PT)if(PT[k].n===num){key=k;el=PT[k];break;}}if(!el){document.getElementById("out-main").textContent="Not Found";document.getElementById("out-unit").textContent="";return;}document.getElementById("out-main").textContent=key;document.getElementById("out-unit").textContent=el.g;document.getElementById("out-detail").innerHTML='<div class="col-4"><div class="p-3 rounded-4 bg-light border text-center"><div class="small fw-bold text-uppercase text-muted mb-1">Atomic #</div><div class="h5 fw-bold mb-0 text-primary">'+el.n+'</div></div></div><div class="col-4"><div class="p-3 rounded-4 bg-light border text-center"><div class="small fw-bold text-uppercase text-muted mb-1">Weight</div><div class="h5 fw-bold mb-0 text-info">'+el.w+' u</div></div></div><div class="col-4"><div class="p-3 rounded-4 bg-light border text-center"><div class="small fw-bold text-uppercase text-muted mb-1">Group</div><div class="h5 fw-bold mb-0 text-success">'+el.g+'</div></div></div>';document.getElementById("out-ins").innerHTML="<p><b>"+key+"</b> (Z="+el.n+") — "+el.g+", atomic weight "+el.w+" u</p>";document.getElementById("res").classList.remove("d-none");});document.getElementById("btn-reset").addEventListener("click",function(){document.getElementById("in-sym").value="Fe";document.getElementById("in-num").value="";document.getElementById("res").classList.add("d-none");});document.getElementById("btn-copy").addEventListener("click",function(){navigator.clipboard.writeText(document.getElementById("out-main").textContent+": "+document.getElementById("out-ins").textContent);var b=this;b.innerHTML="Copied!";setTimeout(function(){b.innerHTML="<i class=\"fas fa-copy me-1\"></i>Copy";},2e3);});});</script>